insert into public.content_page_translations (page_id,language_code,translation_status,seo_title,seo_description,h1,sections) values
((select id from public.content_pages where page_key='privacy_policy'),'en','published','Privacy Policy | Nobel ITBS','Full Nobel ITBS legal document: Privacy Policy.','Privacy Policy','{"slug":"privacy-policy","blocks":[{"heading":"","paragraphs":["This Privacy Policy explains how NOBEL ITBS s.r.o. (“we”, “us” or the “Controller”) processes the personal data of customers and users of online courses (the “User” or “you”) in connection with the sale and provision of digital courses."]},{"heading":"1. Who is the Controller?","paragraphs":["The controller of personal data is:NOBEL ITBS s.r.o.Company ID No.: 23465492Registered office: Vrážská 143, Radotín, 153 00 Prague 5, Czech RepublicRegistered in the Commercial Register maintained by the Municipal Court in Prague, File No. C 427524Contact e-mail: info@nobel-itbs.eu"]},{"heading":"2. What Personal Data Do We Process?","paragraphs":["We may process the following categories of personal data:","a) Identification and contact dataYour first name, surname, e-mail address, and any other information you provide to us when communicating with us.","b) Order and contract-related dataInformation about the course you purchase, the date of purchase, price, currency, order status, and other data necessary for record-keeping and issuing related documents.","c) Course usage data (study and operational data)For example, information about your progress in the course and its completion, such as completed modules, test results and completion status, as well as technical data related to log-in and the operation of the platform (logs), to the extent necessary.","d) Communication dataThe content of communications and related metadata if you contact us, for example by e-mail, through support requests or in connection with complaints.","e) Payment dataWe do not process or store payment data such as payment card details. Such data is processed directly by the payment service provider. We typically receive only a payment confirmation and transaction identifiers necessary for record-keeping and handling related requests."]},{"heading":"3. Why Do We Process Personal Data?","paragraphs":["We process personal data for the following purposes:","a) Entering into and performing the contractThis includes creating access to the course, managing the user account, making course materials available, and ensuring that the service functions properly.","b) Customer support and communicationThis includes handling inquiries, complaints, technical requests, and communication related to the course.","c) Issuing a certificateIf a certificate is included in the course, we process the data necessary for issuing and recording that certificate.","d) Compliance with legal obligationsIn particular, this includes accounting and tax obligations, such as recording transactions and issuing and archiving accounting documents, as well as compliance with obligations towards public authorities.","e) Protection of our legal claims, dispute resolution and securityThis includes protection against misuse, fraud prevention, the enforcement of legal claims, dispute resolution, and maintaining security records related to the operation of the service.","f) Marketing communicationsWe may send you information about our courses and similar services. If you are our customer, we may do so based on our legitimate interests, and you can unsubscribe at any time in an easy way, for example by using the unsubscribe link in an e-mail or by contacting us at info@nobel-itbs.eu. Where required by law, especially in relation to persons who are not our customers, we will send marketing communications only based on consent, which may be withdrawn at any time."]},{"heading":"4. What Are the Legal Bases for Processing?","paragraphs":["We process personal data based on the following legal grounds under Article 6 GDPR:","Performance of a contract under Article 6(1)(b) GDPR, in particular for creating access to the course, maintaining the user account, providing the service, communicating where necessary, and, where applicable, issuing a certificate.","Compliance with a legal obligation under Article 6(1)(c) GDPR, in particular for meeting accounting and tax obligations.","Legitimate interests under Article 6(1)(f) GDPR, in particular for the protection of legal claims, dispute resolution, security, prevention of misuse, and sending marketing communications to existing customers to the extent permitted by law.","Consent under Article 6(1)(a) GDPR, where required, for example for marketing communications sent to persons who are not our customers or for other optional processing activities. Consent may be withdrawn at any time."]},{"heading":"5. Who Do We Share Personal Data With?","paragraphs":["We may share personal data with the following categories of recipients, always only to the extent necessary:","payment service providers for payment processing,","providers of communication services, such as e-mail distribution and customer communication tools,","providers of technical services, such as platform or LMS operators, hosting providers and IT administrators,","content providers or partner organisations, such as a university, where necessary to make the course available and/or issue a certificate,","legal and professional advisers, such as lawyers or auditors, to the extent necessary to protect our rights,","public authorities, where required by law or where necessary for the establishment, exercise or defence of legal claims."]},{"heading":"6. Do We Transfer Personal Data Outside the EU/EEA?","paragraphs":["Some of our suppliers may process personal data outside the EU/EEA. Where such transfers take place, we ensure that appropriate safeguards in accordance with the GDPR are in place, for example standard contractual clauses or other applicable transfer mechanisms, to ensure an adequate level of protection for personal data."]},{"heading":"7. How Long Do We Retain Personal Data?","paragraphs":["We retain personal data only for as long as necessary for the relevant purposes of processing, in particular:","Order data and accounting documents are retained for the period required by applicable accounting and tax laws.","User account and course usage data, including study data, are retained for the duration of access to the course and thereafter for the period necessary to protect legal claims and resolve disputes; typically for 3 years after access to the course ends, unless it is necessary in a specific case to retain the data for longer, for example due to an ongoing dispute, complaint or other proceedings.","Customer communications are retained for the period necessary to handle the relevant request and thereafter for a reasonable period in order to document the communication and protect legal claims.","Marketing communications are retained for as long as there is a lawful basis for sending them, but no longer than until you unsubscribe, object to such processing, or withdraw your consent where consent was required."]},{"heading":"8. What Rights Do You Have?","paragraphs":["Under the GDPR, you have the following rights in particular:","the right of access to your personal data,","the right to rectification of inaccurate personal data,","the right to erasure, if the relevant legal conditions are met,","the right to restriction of processing,","the right to data portability, where applicable,","the right to object to processing based on legitimate interests, including objection to direct marketing,","the right to withdraw consent where processing is based on consent,","the right to lodge a complaint with the supervisory authority.","In the Czech Republic, the supervisory authority is the Office for Personal Data Protection.","You may exercise your rights by contacting us at info@nobel-itbs.eu. We will handle your request within the time limits set out in the GDPR."]},{"heading":"9. Is the Provision of Personal Data Mandatory?","paragraphs":["The provision of certain personal data is necessary for entering into and performing the contract, in particular your e-mail address and order identification details. If you do not provide such data, we may not be able to grant access to the course or provide related services."]},{"heading":"10. How Do We Protect Personal Data?","paragraphs":["We implement appropriate technical and organisational measures to protect personal data, in particular access restrictions, system security measures, and access rights management. In relation to payment data, we rely on the security measures implemented by the payment service provider."]},{"heading":"11. Changes to This Privacy Policy","paragraphs":["We may update this Privacy Policy from time to time, if the scope of our services or the suppliers we use changes. The current version is always available on the Provider’s website."]},{"heading":"12. Contact Details","paragraphs":["If you have any questions or wish to exercise your rights, please contact us at: info@nobel-itbs.eu","Effective date: 1 March 2026"]}]}'::jsonb),
((select id from public.content_pages where page_key='privacy_policy'),'ua','published','Політика конфіденційності | Nobel ITBS','Повний юридичний документ Nobel ITBS: Політика конфіденційності.','Політика конфіденційності','{"slug":"privacy-policy","blocks":[{"heading":"","paragraphs":["компанії NOBEL ITBS s.r.o.","Ця Політика пояснює, як NOBEL ITBS s.r.o. («ми» або «Контролер») обробляє персональні дані замовників і користувачів онлайн-курсів («Користувач» або «ви») у зв''язку з продажем і наданням цифрових курсів."]},{"heading":"1. Хто є Контролером?","paragraphs":["Контролер персональних даних: NOBEL ITBS s.r.o. Ідентифікаційний номер: 23465492 Зареєстрований офіс: Vrážská 143, Radotín, 153 00 Praha 5, Czech Republic Торговий реєстр: Міський суд у Празі, справа № C 427524 Контактний email: info@nobel-itbs.eu"]},{"heading":"2. Які персональні дані ми обробляємо?","paragraphs":["Ми можемо обробляти такі категорії:","a) Ідентифікаційні та контактні дані","Ім''я, прізвище, електронну адресу, **номер телефону** та іншу інформацію, яку ви надаєте під час комунікації з нами.","b) Дані замовлення та договору","Інформацію про придбаний Курс, дату придбання, ціну, валюту, статус замовлення й інші дані для обліку та оформлення пов''язаних документів.","c) Дані використання Курсу","Дані про прогрес і завершення, зокрема пройдені модулі, результати тестів і статус завершення, а також технічні дані входу й роботи Платформи — логи — у необхідному обсязі.","d) Дані комунікації","Зміст повідомлень і пов''язані метадані, якщо ви звертаєтеся email, до підтримки або у зв''язку зі скаргою.","e) Платіжні дані","Ми не обробляємо й не зберігаємо реквізити платіжних карток. Їх безпосередньо обробляє платіжний провайдер. Зазвичай ми отримуємо лише підтвердження платежу й ідентифікатори транзакції для обліку та опрацювання запитів."]},{"heading":"3. Навіщо ми обробляємо дані?","paragraphs":["a) Укладення та виконання договору","Створення доступу, керування Обліковим записом, надання матеріалів і належна робота послуги.","b) Підтримка й комунікація","Опрацювання запитів, скарг, технічних звернень і комунікації щодо Курсу.","c) Видача сертифіката","Якщо сертифікат включений до Курсу, ми обробляємо необхідні для його видачі та обліку дані.","d) Виконання юридичних обов''язків","Зокрема бухгалтерських і податкових обов''язків, обліку транзакцій, видачі та архівування документів і виконання вимог органів влади.","e) Захист прав, вирішення спорів і безпека","Захист від зловживань, запобігання шахрайству, реалізація юридичних вимог, вирішення спорів і ведення записів безпеки.","f) Маркетингові повідомлення","Ми можемо надсилати інформацію про Курси та подібні послуги. Для чинних клієнтів це може ґрунтуватися на законному інтересі в межах, дозволених законом; відписка доступна в будь-який час через посилання або info@nobel-itbs.eu. Коли закон вимагає, зокрема для осіб, які не є клієнтами, повідомлення надсилаються лише на підставі згоди, яку можна відкликати."]},{"heading":"4. Правові підстави","paragraphs":["Відповідно до статті 6 GDPR:","- виконання договору — стаття 6(1)(b), зокрема доступ, Обліковий запис, послуга, необхідна комунікація й, де застосовно, сертифікат; - юридичний обов''язок — стаття 6(1)(c), зокрема бухгалтерські й податкові вимоги; - законні інтереси — стаття 6(1)(f), зокрема захист вимог, спори, безпека, запобігання зловживанням і дозволений маркетинг чинним клієнтам; - згода — стаття 6(1)(a), коли вона потрібна для маркетингу або іншої необов''язкової обробки; згоду можна відкликати."]},{"heading":"5. Кому ми передаємо дані?","paragraphs":["Лише в необхідному обсязі дані можуть передаватися:","- платіжним провайдерам; - сервісам email-розсилок і клієнтської комунікації; - операторам Платформи/LMS, хостингу та IT-адміністраторам; - постачальникам контенту чи партнерським організаціям, зокрема університету, коли це необхідно для надання Курсу та/або видачі сертифіката; - юристам, аудиторам та іншим професійним радникам; - органам влади, якщо цього вимагає закон або захист юридичних вимог."]},{"heading":"6. Чи передаємо ми дані за межі ЄС/ЄЕЗ?","paragraphs":["Деякі постачальники можуть обробляти дані за межами ЄС/ЄЕЗ. У такому разі ми забезпечуємо належні гарантії GDPR, наприклад стандартні договірні положення або інший застосовний механізм передачі."]},{"heading":"7. Як довго ми зберігаємо дані?","paragraphs":["- дані замовлень і бухгалтерські документи — протягом строку, установленого бухгалтерським і податковим законодавством; - дані Облікового запису, використання й навчання — протягом доступу та після нього стільки, скільки потрібно для захисту вимог і спорів, зазвичай 3 роки після завершення доступу, якщо конкретна справа не потребує довшого строку; - комунікацію — протягом опрацювання звернення та розумного строку після цього для документування й захисту вимог; - маркетингові дані — доки є законна підстава, але не довше відписки, заперечення або відкликання згоди."]},{"heading":"8. Ваші права","paragraphs":["Відповідно до GDPR ви маєте, зокрема:","- право на доступ; - право на виправлення неточних даних; - право на видалення за наявності законних умов; - право на обмеження обробки; - право на перенесення даних, де застосовно; - право заперечити проти обробки на підставі законного інтересу, включно з прямим маркетингом; - право відкликати згоду; - право подати скаргу до наглядового органу.","У Чеській Республіці наглядовим органом є Управління із захисту персональних даних. Для реалізації прав звертайтеся на info@nobel-itbs.eu. Запит буде опрацьовано у строки GDPR."]},{"heading":"9. Чи обов''язково надавати дані?","paragraphs":["Певні дані, зокрема email та ідентифікаційні дані замовлення, необхідні для укладення й виконання договору. Без них ми можемо не мати змоги відкрити доступ до Курсу або надати пов''язані послуги."]},{"heading":"10. Як ми захищаємо дані?","paragraphs":["Ми застосовуємо належні технічні й організаційні заходи, зокрема обмеження доступу, системні заходи безпеки та керування правами доступу. Для платіжних даних покладаємося на заходи платіжного провайдера."]},{"heading":"11. Зміни Політики","paragraphs":["Ми можемо оновлювати Політику через зміни послуг або постачальників. Актуальна версія завжди доступна на вебсайті Постачальника."]},{"heading":"12. Контакти","paragraphs":["Запитання та звернення щодо прав: info@nobel-itbs.eu.","Дата набрання чинності: 1 березня 2026 року."]},{"heading":"Примітка для Release 1 — не публікувати як частину Політики","paragraphs":["Перед запуском credential registry юрист має погодити доповнення щодо відвідувачів сайту, форм звернень, CAPTCHA й rate limiting, профілів слухачів, реєстру документів і QR-токенів, публічної верифікації, приватного PDF-сховища, email-доставлення, адміністраторів і журналів аудиту, фактичних постачальників, ролей контролера/процесора, строків зберігання та даних, отриманих від партнерів."]}]}'::jsonb),
((select id from public.content_pages where page_key='privacy_policy'),'cz','published','Zásady ochrany osobních údajů | Nobel ITBS','Úplný právní dokument Nobel ITBS: Zásady ochrany osobních údajů.','Zásady ochrany osobních údajů','{"slug":"privacy-policy","blocks":[{"heading":"","paragraphs":["Tento dokument vysvětluje, jak společnost NOBEL ITBS s.r.o. („my“, „Správce“) zpracovává osobní údaje zákazníků a uživatelů online kurzů (dále jen „Uživatel“ nebo „Vy“) v souvislosti s prodejem a poskytováním digitálních kurzů."]},{"heading":"1. Kdo je správcem osobních údajů","paragraphs":["Správcem osobních údajů je společnost:NOBEL ITBS s.r.o., IČO: 23465492sídlo: Vrážská 143, Radotín, 153 00 Praha 5, Česká republikazapsaná v obchodním rejstříku vedeném Městským soudem v Praze, sp. zn. C 427524kontaktní e-mail: info@nobel-itbs.eu"]},{"heading":"2. Jaké osobní údaje zpracováváme","paragraphs":["Zpracováváme zejména tyto kategorie osobních údajů:","a) Identifikační a kontaktní údajejméno a příjmení, e-mail, případně další údaje, které nám sdělíte při komunikaci.","b) Údaje o objednávce a plnění smlouvyinformace o zakoupeném kurzu, datu nákupu, ceně, měně, stavu objednávky a údaje potřebné pro evidenci plnění a vystavení dokladů.","c) Údaje o užívání kurzu (studijní a provozní údaje)např. údaje o průběhu studia a plnění kurzu (absolvované moduly, výsledky testů, stav dokončení), údaje související s přihlášením a technickým provozem platformy (logy), a to v nezbytném rozsahu.","d) Komunikační údajeobsah a metadata komunikace, pokud nás kontaktujete (e-mailové zprávy, požadavky na podporu, reklamace).","e) Platební údajePlatební údaje (např. číslo platební karty) nezpracováváme a neuchováváme. Zpracovává je přímo poskytovatel platebních služeb. My obvykle obdržíme pouze potvrzení o platbě a identifikátory transakce potřebné pro evidenci a vyřízení požadavků."]},{"heading":"3. Proč osobní údaje zpracováváme (účely)","paragraphs":["Osobní údaje zpracováváme zejména za těmito účely:","a) Uzavření a plnění smlouvy (poskytnutí kurzu)zřízení přístupu ke kurzu, správa uživatelského účtu, zpřístupnění materiálů, zajištění funkčnosti služby.","b) Zákaznická podpora a komunikacevyřízení dotazů, reklamací, technických požadavků, komunikace související s kurzem.","c) Vydání certifikátu (pokud je součástí kurzu)pokud je certifikát součástí kurzu, zpracování údajů potřebných k jeho vystavení a evidenci.","d) Splnění právních povinnostízejména účetní a daňové povinnosti (evidence transakcí, vystavování a archivace dokladů) a plnění povinností vůči orgánům veřejné moci.","e) Ochrana našich právních nároků, řešení sporů a bezpečnostochrana proti zneužití, řešení sporů a uplatňování nároků, prevence podvodů a bezpečnostní záznamy související s provozem služby.","f) Marketingová komunikacezasílání informací o našich kurzech a obdobných službách. Jste-li naším zákazníkem, můžeme Vám zasílat taková sdělení zejména na základě našeho oprávněného zájmu, přičemž se můžete kdykoli jednoduše odhlásit (např. odkazem v e-mailu nebo e-mailem na info@nobel-itbs.eu). V případech, kdy právní předpisy vyžadují souhlas (např. u osob, které nejsou zákazníky), budeme marketing zasílat pouze na základě souhlasu, který lze kdykoli odvolat."]},{"heading":"4. Právní základy zpracování (čl. 6 GDPR)","paragraphs":["Zpracování provádíme na základě těchto právních titulů:","Plnění smlouvy (čl. 6 odst. 1 písm. b) GDPR) – zejména pro zřízení přístupu ke kurzu, vedení účtu, komunikaci nutnou pro poskytnutí služby a případně vydání certifikátu.","Splnění právní povinnosti (čl. 6 odst. 1 písm. c) GDPR) – zejména účetní a daňové povinnosti.","Oprávněný zájem (čl. 6 odst. 1 písm. f) GDPR) – zejména ochrana právních nároků, řešení sporů, bezpečnost a prevence zneužití, a dále zasílání marketingových sdělení stávajícím zákazníkům v zákonném rozsahu.","Souhlas (čl. 6 odst. 1 písm. a) GDPR) – pouze tam, kde je vyžadován (např. marketing pro osoby, které nejsou zákazníky, nebo jiná volitelná zpracování). Souhlas lze kdykoli odvolat."]},{"heading":"5. Komu osobní údaje předáváme (příjemci)","paragraphs":["Osobní údaje můžeme předávat těmto kategoriím příjemců, vždy pouze v nezbytném rozsahu:","poskytovatelům platebních služeb (zajištění plateb),","poskytovatelům komunikačních služeb (např. nástroje pro rozesílku e-mailů a zákaznickou komunikaci),","poskytovatelům technických služeb (např. provoz platformy/LMS, hosting, správa IT),","poskytovateli obsahu / partnerské organizaci (např. univerzitě), pokud je to nezbytné k zpřístupnění kurzu a/nebo vydání certifikátu,","právním a odborným poradcům (např. advokáti, auditoři) v rozsahu nezbytném k ochraně našich práv,","orgánům veřejné moci, vyžaduje-li to právní předpis nebo je-li to nezbytné pro uplatnění právních nároků."]},{"heading":"6. Předávání osobních údajů mimo EU/EHP","paragraphs":["Někteří naši dodavatelé mohou zpracovávat osobní údaje mimo EU/EHP. Pokud k takovému předávání dochází, zajišťujeme odpovídající záruky dle GDPR (např. standardní smluvní doložky nebo jiné mechanismy), aby byla zajištěna odpovídající úroveň ochrany osobních údajů."]},{"heading":"7. Jak dlouho údaje uchováváme (doby uchování)","paragraphs":["Osobní údaje uchováváme pouze po dobu nezbytnou pro účely zpracování, zejména:","Údaje o objednávkách a účetních dokladech: po dobu vyžadovanou účetními a daňovými předpisy.","Uživatelský účet a údaje o užívání kurzu (včetně studijních údajů): po dobu trvání přístupu ke kurzu a dále po dobu nezbytnou pro ochranu právních nároků a řešení sporů; typicky 3 roky od skončení přístupu ke kurzu, není-li v konkrétním případě nezbytné uchovávat údaje déle (např. probíhající spor, reklamace nebo jiné řízení).","Komunikace se zákazníkem: po dobu nezbytnou k vyřízení požadavku a dále po přiměřenou dobu pro doložení komunikace a ochranu právních nároků.","Marketingová komunikace: po dobu, po kterou trvá oprávněný důvod pro zasílání sdělení, nejdéle však do doby, než se odhlásíte nebo vznesete námitku (případně odvoláte souhlas, pokud byl vyžadován)."]},{"heading":"8. Jaká máte práva","paragraphs":["V souladu s GDPR máte zejména tato práva:","právo na přístup k osobním údajům,","právo na opravu nepřesných údajů,","právo na výmaz, pokud jsou splněny podmínky (zejména pokud už údaje nejsou potřebné pro účely, pro které byly zpracovávány, nebo pokud odvoláte souhlas a neexistuje jiný právní základ),","právo na omezení zpracování,","právo na přenositelnost údajů (v relevantních případech),","právo vznést námitku proti zpracování založenému na oprávněném zájmu, včetně námitky proti marketingu,","právo odvolat souhlas (je-li zpracování založeno na souhlasu),","právo podat stížnost u dozorového úřadu, kterým je v České republice Úřad pro ochranu osobních údajů (ÚOOÚ).","Svou žádost můžete uplatnit na e-mailu info@nobel-itbs.eu. Žádost vyřídíme ve lhůtách stanovených GDPR."]},{"heading":"9. Povinnost poskytnout údaje","paragraphs":["Poskytnutí některých osobních údajů je nezbytné pro uzavření a plnění smlouvy (zejména e-mail a identifikace objednávky). Pokud nám tyto údaje neposkytnete, nemusíme být schopni zpřístupnit Kurz nebo poskytnout související služby."]},{"heading":"10. Zabezpečení osobních údajů","paragraphs":["Přijímáme přiměřená technická a organizační opatření k ochraně osobních údajů, zejména omezení přístupů, zabezpečení systémů a řízení přístupových oprávnění. U platebních údajů spoléháme na zabezpečení poskytovatele platebních služeb."]},{"heading":"11. Změny těchto zásad","paragraphs":["Tyto Zásady můžeme průběžně aktualizovat, zejména při změně rozsahu služeb nebo dodavatelů. Aktuální znění je vždy dostupné na webu Poskytovatele."]},{"heading":"12. Kontaktní údaje","paragraphs":["V případě dotazů či uplatnění práv nás kontaktujte: info@nobel-itbs.eu.","Účinnost: 1. 3. 2026"]}]}'::jsonb),
((select id from public.content_pages where page_key='terms_of_use'),'en','published','Terms of Use (Public Contract) | Nobel ITBS','Full Nobel ITBS legal document: Terms of Use (Public Contract).','Terms of Use (Public Contract)','{"slug":"terms-of-use","blocks":[{"heading":"","paragraphs":["These Terms of Use (the “Terms”) govern the rights and obligations between NOBEL ITBS s.r.o., as the seller/provider of digital content, and customers when ordering and using online educational courses (the “Course”). The Terms form part of the distance contract concluded through the Provider’s web interface."]},{"heading":"1. Provider identification and contact details","paragraphs":["1.1 The provider and seller is NOBEL ITBS s.r.o., Company ID No.: 23465492, with its registered office at Vrážská 143, Radotín, 153 00 Prague 5, Czech Republic, registered in the Commercial Register maintained by the Municipal Court in Prague, File No. C 427524 (the “Provider”).","1.2 Contact e-mail: info@nobel-itbs.eu.","1.3 These Terms are available on the Provider’s website, and the Buyer has the opportunity to save and print them before submitting the order."]},{"heading":"2. Definitions","paragraphs":["2.1 “Buyer” means a natural person or legal entity entering into a contract with the Provider for the provision of the Course.","2.2 “Consumer” means a natural person who, when concluding and performing the contract, is not acting within the scope of their business activity or profession.","2.3 “Business Customer” means a person acting within the scope of their business activity or profession; in the case of a legal entity, it is presumed to act as a business customer.","2.4 “Course” means an online educational programme provided as digital content and/or a digital service, in particular in the form of access to educational materials (such as videos, texts, tests, assignments) through a third-party platform (such as Moodle/LMS) and/or by making digital materials available for download, in accordance with the Course Description.","2.5 “Platform” means the online environment (such as an LMS) through which the Course is made available to the Buyer.","2.6 “User Account” means the Buyer’s account on the Platform or in the Provider’s system through which the Buyer uses the Course.","2.7 “Access Credentials” means the data enabling login to the User Account.","2.8 “Partner / Content Provider” means a third party (such as a partner university) that owns the intellectual property rights to the Course content (the “Content Provider”).","2.9 “Course Description” means the description of the Course published on the Provider’s website (in particular its content, scope, access period, price and any other conditions).","2.10 “Contract” means the contract concluded between the Provider and the Buyer on the basis of the Order under these Terms."]},{"heading":"3. Course information and technical requirements","paragraphs":["3.1 The Course, its content, scope, price, access period and other parameters are specified in the Course Description.","3.2 The Buyer acknowledges that the Course is provided online and that its use generally requires an internet connection, a compatible device (PC/tablet/mobile phone), an up-to-date web browser and a functioning e-mail address.","3.3 The Provider shall use reasonable efforts to ensure that the Course is available. However, the Buyer acknowledges that temporary limitations in availability may occur due to maintenance, updates, force majeure or circumstances on the part of third parties (such as the provider of the Platform/hosting)."]},{"heading":"4. Order and conclusion of the contract","paragraphs":["4.1 The Buyer places an order for the Course through the Provider’s web interface.","4.2 Before submitting the order, the Buyer has the opportunity to review and correct the entered data.","4.3 By submitting the order, the Buyer confirms that they have read and agree to these Terms.","4.4 The Contract is concluded at the moment when the Provider either (i) confirms receipt of the order to the Buyer by e-mail, or (ii) makes the Course available to the Buyer (for example by sending access credentials or activating the User Account), whichever occurs first.","4.5 The Provider is not obliged to conclude the Contract, in particular in the event of an obvious pricing error, misuse of the system, suspicion of fraudulent conduct, or if the Buyer has previously materially breached these Terms."]},{"heading":"5. Price, payment terms and currency","paragraphs":["5.1 The price of the Course is stated in the Course Description.","5.2 As of the effective date of these Terms, the Provider is not a VAT payer. If the Provider becomes a VAT payer in the future, Course prices shall be stated and charged in accordance with applicable law, i.e. either (i) as prices including VAT, or (ii) as prices excluding VAT, together with the applicable VAT amount and rate, always according to how the price of the particular Course is presented in the Course Description.","5.3 Payment shall be made cashlessly through a payment gateway (such as Stripe) or by another method specified in the ordering process.","5.4 Payment is deemed made at the moment of confirmation of a successful transaction by the payment gateway or upon crediting the amount to the Provider’s account (depending on the selected payment method).","5.5 If the price is displayed indicatively in another currency (such as UAH), the Buyer acknowledges that the final conversion and any related fees are determined by the issuing bank of the payment card or the payment service provider. The Provider shall not be liable for exchange rate differences or fees associated with currency conversion.","5.6 The Provider does not store the Buyer’s payment details; such data is processed directly by the payment service provider."]},{"heading":"6. Making the Course available, user account and cooperation","paragraphs":["6.1 After payment of the price, the Provider shall make the Course available to the Buyer without undue delay after receipt of payment, and no later than within 24 hours, unless the Course Description states otherwise.","6.2 The Buyer is obliged to provide truthful and complete information necessary for the creation of the User Account and for the delivery of information (in particular an e-mail address).","6.3 The Buyer is obliged to protect the Access Credentials and prevent them from being disclosed to third parties. The Buyer is responsible for all use of the Course through their account.","6.4 The Provider shall not be liable for failure to deliver the Access Credentials due to an incorrectly entered e-mail address, the Buyer’s mailbox settings, spam filtering, or circumstances on the Buyer’s side."]},{"heading":"7. Course access period and changes to the Course/Platform","paragraphs":["7.1 The access period for the Course is stated in the Course Description. Unless stated otherwise, access is provided for 12 months from the date the Course is made available.","7.2 The Provider is entitled to make reasonable changes to the Course and the Platform (for example updates, changes in the order of modules, or changes in the technical solution), provided that this does not result in a substantial deterioration in the availability or functionality of the Course for the Buyer.","7.3 If such a change substantially worsens the Buyer’s ability to use the Course, the Buyer shall have rights arising from defective performance under Article 10 of these Terms."]},{"heading":"8. Licence and conditions of use of content (intellectual property)","paragraphs":["8.1 The content of the Course (in particular videos, texts, presentations, methodologies, tests, graphics, question databases and other materials) is protected by intellectual property laws and belongs to the Content Provider and/or the Provider, unless stated otherwise.","8.2 The Provider grants the Buyer a non-exclusive, non-transferable, territorially unlimited and time-limited licence to use the Course content solely for the Buyer’s personal educational purposes, for the duration of access to the Course.","8.3 In particular, the Buyer may not:","a) make copies, screen recordings, reproductions, or otherwise reproduce the Course content beyond ordinary personal use;","b) share Access Credentials, allow third parties to use the Course, or “share an account”;","c) publish, distribute, sell, rent, sublicense, or otherwise commercially exploit the Course content;","d) circumvent technical protection measures, interfere with the Platform, or compromise its security;","e) extract the database of test questions or Course content by automated means.","8.4 A breach of this Article constitutes a material breach of the Contract. In such a case, the Provider is entitled to restrict or block the Buyer’s access to the Course, even without prior notice if the nature of the breach so requires. This shall not affect the Provider’s claims for damages."]},{"heading":"9. Certificate (if included in the Course)","paragraphs":["9.1 If the Course Description states that a certificate is included in the Course, the certificate shall be issued under the conditions specified in the Course Description.","9.2 The Buyer acknowledges that the certificate is a confirmation of completion of the Course within the Provider’s/Content Provider’s system and may not constitute a public-law qualification or recognition under applicable law, unless expressly stated otherwise.","9.3 The Provider is entitled not to issue the certificate or to invalidate it if fraudulent conduct is detected (for example account misuse or manipulation of tests)."]},{"heading":"10. Liability for defects in digital content and complaints","paragraphs":["10.1 The Course is provided as digital content. The Provider is liable, in particular to the Consumer, for ensuring that at the time the Course is made available and throughout the access period it corresponds to the agreed characteristics and is free from defects.","10.2 A defect shall mean in particular a situation where the Course is not available, does not function in the usual manner, does not correspond to the Course Description, or cannot be used on ordinary devices when the technical requirements are met.","10.3 The Buyer shall submit a complaint without undue delay by e-mail to info@nobel-itbs.eu and shall include a description of the defect, identification of the order, and, where applicable, materials allowing the defect to be reproduced.","10.4 The Provider shall handle the complaint within a reasonable time; in the case of a Consumer, no later than within the time limits set by applicable law. The Provider may remedy the defect, provide substitute access, grant a reasonable discount on the price, or allow withdrawal from the Contract, if required by the nature of the defect and applicable law.","10.5 The Buyer is obliged to provide the Provider with reasonable cooperation necessary for the verification and remedy of the defect."]},{"heading":"11. Withdrawal from the contract, cancellations and refunds","paragraphs":["11.1 If the Buyer is a Consumer, they generally have the right to withdraw from the Contract concluded at a distance within 14 days from the date of conclusion of the Contract, provided that provision of the Course has not yet begun.","11.2 The Buyer – Consumer acknowledges and is hereby expressly informed that the Course constitutes digital content which is generally made available immediately after payment of the price. By submitting the order and paying the price, the Consumer expressly requests that the Provider begin providing the Course before the expiry of the withdrawal period and acknowledges that at the moment the provision of the Course begins (i.e. when the Course is made available, in particular by activation of the User Account, sending of the Access Credentials or making digital materials available), the Consumer loses the right to withdraw from the Contract.","11.3 If the Consumer withdraws from the Contract at a time when provision of the Course within the meaning of Article 11.2 has not yet begun, the Provider shall refund the received funds without undue delay, no later than within the period set by applicable law, using the same payment method that was used to make the original payment, unless the parties agree otherwise.","11.4 Details regarding refunds and the practical procedure are set out in the document “Refund Policy / Podmínky vrácení peněz” available on the Provider’s website. In the event of any conflict between the Refund Policy and these Terms, these Terms shall prevail.","11.5 In the case of Business Customers, the right of withdrawal shall be governed by law and these Terms; the provisions on consumer withdrawal shall not apply."]},{"heading":"12. Personal data protection","paragraphs":["12.1 The Provider processes the personal data of Buyers in accordance with applicable law, in particular the GDPR. Information on the processing of personal data is set out in the document “Privacy Policy / Zásady ochrany osobních údajů” available on the Provider’s website.","12.2 The Buyer acknowledges that, for the purpose of making the Course available on the Platform and, where applicable, for issuing a certificate, it may be necessary to transfer certain data to the Content Provider or the operator of the Platform, to the extent necessary for performance of the Contract."]},{"heading":"13. Language versions","paragraphs":["13.1 These Terms may be made available in Czech and in other language versions. In the event of any conflict between language versions, the Czech version shall prevail."]},{"heading":"14. Final provisions, governing law and dispute resolution","paragraphs":["14.1 The Contract and these Terms shall be governed by the laws of the Czech Republic.","14.2 The Provider and the Buyer undertake to resolve any mutual disputes primarily amicably.","14.3 If the Buyer is a Consumer, they have the right to out-of-court resolution of a consumer dispute. The competent body for out-of-court dispute resolution is the Czech Trade Inspection Authority (ČOI). Details are available on the ČOI website.","14.4 If any provision of these Terms is or becomes invalid or ineffective, this shall not affect the validity of the remaining provisions.","14.5 The Provider is entitled to amend these Terms to a reasonable extent; the change shall be announced in an appropriate manner. The version effective at the time of conclusion of the Contract shall be binding on the Buyer, unless applicable law requires otherwise.","14.6 These Terms shall become effective on 1 March 2026."]}]}'::jsonb),
((select id from public.content_pages where page_key='terms_of_use'),'ua','published','Умови (Публічний договір) | Nobel ITBS','Повний юридичний документ Nobel ITBS: Умови (Публічний договір).','Умови (Публічний договір)','{"slug":"terms-of-use","blocks":[{"heading":"","paragraphs":["щодо надання онлайн-освітніх курсів компанією NOBEL ITBS s.r.o.","Ці Умови використання («Умови») регулюють права та обов''язки між NOBEL ITBS s.r.o. як продавцем/постачальником цифрового контенту та замовниками під час замовлення й використання онлайн-освітніх курсів («Курс»). Умови є частиною дистанційного договору, укладеного через вебінтерфейс Постачальника."]},{"heading":"1. Ідентифікація та контактні дані Постачальника","paragraphs":["1.1. Постачальником і продавцем є NOBEL ITBS s.r.o., ідентифікаційний номер: 23465492, зареєстрований офіс: Vrážská 143, Radotín, 153 00 Praha 5, Czech Republic, зареєстрована в Торговому реєстрі, який веде Міський суд у Празі, справа № C 427524 («Постачальник»).","1.2. Контактний email: info@nobel-itbs.eu.","1.3. Ці Умови доступні на вебсайті Постачальника. До надсилання замовлення Покупець може їх зберегти та роздрукувати."]},{"heading":"2. Визначення","paragraphs":["2.1. «Покупець» — фізична або юридична особа, яка укладає з Постачальником договір про надання Курсу.","2.2. «Споживач» — фізична особа, яка під час укладення та виконання договору не діє в межах підприємницької діяльності чи професії.","2.3. «Бізнес-клієнт» — особа, яка діє в межах підприємницької діяльності чи професії; юридична особа презюмується бізнес-клієнтом.","2.4. «Курс» — онлайн-освітня програма, що надається як цифровий контент та/або цифрова послуга, зокрема через доступ до відео, текстів, тестів і завдань на сторонній платформі, наприклад Moodle/LMS, та/або через надання цифрових матеріалів для завантаження відповідно до Опису курсу.","2.5. «Платформа» — онлайн-середовище, через яке Курс доступний Покупцеві.","2.6. «Обліковий запис» — обліковий запис Покупця на Платформі або в системі Постачальника, через який використовується Курс.","2.7. «Дані доступу» — дані для входу до Облікового запису.","2.8. «Партнер / Постачальник контенту» — третя сторона, наприклад партнерський університет, якій належать права інтелектуальної власності на зміст Курсу.","2.9. «Опис курсу» — опублікований на вебсайті опис змісту, обсягу, строку доступу, ціни та інших умов Курсу.","2.10. «Договір» — договір між Постачальником і Покупцем, укладений на підставі Замовлення відповідно до цих Умов."]},{"heading":"3. Інформація про Курс і технічні вимоги","paragraphs":["3.1. Зміст, обсяг, ціна, строк доступу та інші параметри визначені в Описі курсу.","3.2. Курс надається онлайн і зазвичай потребує інтернет-з''єднання, сумісного пристрою, актуального браузера та робочої електронної адреси.","3.3. Постачальник докладає розумних зусиль для доступності Курсу. Тимчасові обмеження можливі через обслуговування, оновлення, форс-мажор або обставини на боці третіх сторін, зокрема Платформи чи хостингу."]},{"heading":"4. Замовлення та укладення Договору","paragraphs":["4.1. Покупець оформлює замовлення через вебінтерфейс Постачальника.","4.2. До надсилання замовлення Покупець може перевірити та виправити введені дані.","4.3. Надсилаючи замовлення, Покупець підтверджує ознайомлення та згоду з цими Умовами.","4.4. Договір укладається, коли Постачальник або підтверджує отримання замовлення email-повідомленням, або надає доступ до Курсу, залежно від того, що відбудеться раніше.","4.5. Постачальник не зобов''язаний укладати Договір, зокрема у разі очевидної помилки в ціні, зловживання системою, підозри шахрайства або попереднього істотного порушення цих Умов Покупцем."]},{"heading":"5. Ціна, оплата та валюта","paragraphs":["5.1. Ціна зазначається в Описі курсу.","5.2. На дату набрання чинності Умовами Постачальник не є платником ПДВ. Якщо це зміниться, ціни зазначатимуться та стягуватимуться відповідно до закону й способу представлення ціни конкретного Курсу.","5.3. Оплата здійснюється безготівково через платіжний шлюз, зокрема Stripe, або іншим способом, указаним під час замовлення.","5.4. Оплата вважається здійсненою після підтвердження успішної транзакції платіжним шлюзом або зарахування коштів на рахунок Постачальника.","5.5. Якщо іншу валюту, наприклад UAH, показано орієнтовно, остаточний курс і комісії визначає банк-емітент або платіжний провайдер. Постачальник не відповідає за курсові різниці та комісії конвертації.","5.6. Постачальник не зберігає платіжні реквізити Покупця; їх обробляє платіжний провайдер."]},{"heading":"6. Надання доступу, обліковий запис і співпраця","paragraphs":["6.1. Після оплати Постачальник надає доступ без невиправданої затримки, не пізніше 24 годин після отримання оплати, якщо Опис курсу не передбачає інше.","6.2. Покупець надає правдиві й повні дані, необхідні для Облікового запису та доставлення інформації, зокрема email.","6.3. Покупець захищає Дані доступу від третіх сторін і відповідає за використання Курсу через свій Обліковий запис.","6.4. Постачальник не відповідає за недоставлення Даних доступу через помилковий email, налаштування скриньки, спам-фільтри чи інші обставини на боці Покупця."]},{"heading":"7. Строк доступу та зміни Курсу/Платформи","paragraphs":["7.1. Строк зазначено в Описі курсу. Якщо не вказано інше, доступ надається на 12 місяців від дати відкриття Курсу.","7.2. Постачальник може вносити розумні зміни, наприклад оновлювати зміст, порядок модулів або технічне рішення, якщо це істотно не погіршує доступність чи функціональність.","7.3. У разі істотного погіршення Покупець має права, що випливають з неналежного виконання відповідно до статті 10."]},{"heading":"8. Ліцензія та використання контенту","paragraphs":["8.1. Контент Курсу захищений правом інтелектуальної власності та належить Постачальнику контенту та/або Постачальнику, якщо не зазначено інше.","8.2. Покупцеві надається невиключна, непередавана, територіально необмежена та строкова ліцензія лише для особистих освітніх цілей протягом строку доступу.","8.3. Покупець не може: відтворювати контент понад звичайне особисте використання; передавати Дані доступу чи спільно використовувати обліковий запис; публікувати, поширювати, продавати, здавати в оренду, субліцензувати або комерційно використовувати контент; обходити технічний захист чи втручатися в Платформу; автоматизовано вилучати бази тестових запитань або контент.","8.4. Порушення цієї статті є істотним порушенням Договору. Постачальник може обмежити або заблокувати доступ, за потреби без попередження, зі збереженням права на відшкодування збитків."]},{"heading":"9. Сертифікат, якщо він включений до Курсу","paragraphs":["9.1. Сертифікат видається за умовами, указаними в Описі курсу.","9.2. Сертифікат підтверджує завершення Курсу в системі Постачальника або Постачальника контенту й може не становити публічно-правової кваліфікації чи визнання, якщо прямо не зазначено інше.","9.3. Постачальник може не видати або анулювати сертифікат у разі виявлення шахрайства, зокрема зловживання обліковим записом чи маніпуляції тестами."]},{"heading":"10. Недоліки цифрового контенту та скарги","paragraphs":["10.1. Постачальник відповідає, зокрема перед Споживачем, за відповідність Курсу погодженим характеристикам і відсутність недоліків під час надання та строку доступу.","10.2. Недоліком є, зокрема, недоступність, неналежна робота, невідповідність Опису або неможливість використання на звичайному пристрої за дотримання вимог.","10.3. Скарга подається без невиправданої затримки на info@nobel-itbs.eu із описом недоліку, ідентифікацією замовлення та, за можливості, матеріалами для відтворення проблеми.","10.4. Постачальник розглядає скаргу в розумний строк, а щодо Споживача — не пізніше строку, установленого законом. Він може усунути недолік, надати альтернативний доступ, знижку або дозволити відмову від Договору.","10.5. Покупець надає розумне сприяння для перевірки й усунення недоліку."]},{"heading":"11. Відмова від Договору, скасування та повернення коштів","paragraphs":["11.1. Споживач загалом має право відмовитися від дистанційного Договору протягом 14 днів від укладення, якщо надання Курсу ще не почалося.","11.2. Курс є цифровим контентом, який зазвичай надається одразу після оплати. Надсилаючи замовлення та сплачуючи ціну, Споживач прямо просить почати надання до завершення строку відмови й визнає, що з моменту відкриття Курсу, активації Облікового запису, надсилання Даних доступу або надання цифрових матеріалів втрачає право на відмову.","11.3. Якщо Споживач відмовився до початку надання, Постачальник повертає кошти без невиправданої затримки, не пізніше законного строку, тим самим способом, якщо сторони не домовилися інакше.","11.4. Деталі наведено в «Політиці повернення коштів». У разі суперечності перевагу мають ці Умови.","11.5. Для Бізнес-клієнтів право на відмову регулюється законом і цими Умовами; споживчі положення не застосовуються."]},{"heading":"12. Захист персональних даних","paragraphs":["12.1. Дані обробляються відповідно до закону, зокрема GDPR. Деталі містить «Політика конфіденційності» на вебсайті.","12.2. Для надання Курсу та, де застосовно, видачі сертифіката певні дані можуть передаватися Постачальнику контенту або оператору Платформи в необхідному для виконання Договору обсязі."]},{"heading":"13. Мовні версії","paragraphs":["13.1. Умови можуть бути доступні чеською та іншими мовами. У разі розбіжностей перевагу має чеська версія."]},{"heading":"14. Прикінцеві положення, право та спори","paragraphs":["14.1. Договір і Умови регулюються законодавством Чеської Республіки.","14.2. Сторони насамперед намагатимуться вирішувати спори мирно.","14.3. Споживач має право на позасудове вирішення спору компетентним органом — Чеською торговою інспекцією (ČOI). Деталі доступні на вебсайті ČOI.","14.4. Недійсність або неефективність окремого положення не впливає на решту.","14.5. Постачальник може в розумному обсязі змінити Умови та повідомити про це. Для Покупця обов''язкова версія, чинна на момент укладення Договору, якщо закон не передбачає інше.","14.6. Умови набирають чинності 1 березня 2026 року."]}]}'::jsonb),
((select id from public.content_pages where page_key='terms_of_use'),'cz','published','Podmínky používání (obchodní podmínky) | Nobel ITBS','Úplný právní dokument Nobel ITBS: Podmínky používání (obchodní podmínky).','Podmínky používání (obchodní podmínky)','{"slug":"terms-of-use","blocks":[{"heading":"","paragraphs":["Tyto Podmínky používání (dále jen „Podmínky“) upravují práva a povinnosti mezi společností NOBEL ITBS s.r.o. jako prodávajícím/poskytovatelem digitálního plnění a zákazníky při objednávání a užívání online vzdělávacích kurzů (dále jen „Kurz“). Podmínky jsou součástí smlouvy uzavírané na dálku prostřednictvím webového rozhraní Poskytovatele."]},{"heading":"1. Identifikace poskytovatele a kontaktní údaje","paragraphs":["1.1 Poskytovatelem a prodávajícím je společnost NOBEL ITBS s.r.o., IČO: 23465492, se sídlem Vrážská 143, Radotín, 153 00 Praha 5, Česká republika, zapsaná v obchodním rejstříku vedeném Městským soudem v Praze, sp. zn. C 427524 (dále jen „Poskytovatel“).1.2 Kontaktní e-mail: info@nobel-itbs.eu.1.3 Podmínky jsou dostupné na webu Poskytovatele a Kupující má možnost si je před odesláním objednávky uložit a vytisknout."]},{"heading":"2. Vymezení pojmů","paragraphs":["2.1 „Kupující“ je fyzická nebo právnická osoba, která uzavírá s Poskytovatelem smlouvu o poskytnutí Kurzu.2.2 „Spotřebitel“ je fyzická osoba, která při uzavírání a plnění smlouvy nejedná v rámci své podnikatelské činnosti ani výkonu povolání.2.3 „Podnikatel“ je osoba, která jedná v rámci své podnikatelské činnosti nebo výkonu povolání; u právnické osoby se má za to, že jedná jako podnikatel.2.4 „Kurz“ je online vzdělávací program poskytovaný jako digitální obsah a/nebo digitální služba, zejména formou přístupu k výukovým materiálům (např. videím, textům, testům, úkolům) prostřednictvím platformy třetí strany (např. Moodle/LMS) a/nebo formou zpřístupnění digitálních materiálů ke stažení, podle Popisu Kurzu.2.5 „Platforma“ je online prostředí (např. LMS), prostřednictvím kterého je Kupujícímu zpřístupněn Kurz.2.6 „Uživatelský účet“ je účet Kupujícího na Platformě nebo v systému Poskytovatele, prostřednictvím kterého Kupující Kurz užívá.2.7 „Přístupové údaje“ jsou údaje umožňující přihlášení do Uživatelského účtu.2.8 „Partner / Poskytovatel obsahu“ je třetí osoba (např. partnerská univerzita), která je vlastníkem duševního vlastnictví k obsahu Kurzu (dále jen „Poskytovatel obsahu“).2.9 „Popis Kurzu“ je popis Kurzu zveřejněný na webu Poskytovatele (zejména obsah, rozsah, doba přístupu, cena a případné další podmínky).2.10 „Smlouva“ je smlouva uzavřená mezi Poskytovatelem a Kupujícím na základě Objednávky dle těchto Podmínek."]},{"heading":"3. Informace o Kurzu a technické požadavky","paragraphs":["3.1 Kurz, jeho obsah, rozsah, cena, doba přístupu a další parametry jsou uvedeny v Popisu Kurzu.3.2 Kupující bere na vědomí, že Kurz je poskytován online a pro jeho užívání je zpravidla nezbytné připojení k internetu, kompatibilní zařízení (PC/tablet/mobil), aktuální webový prohlížeč a funkční e-mailová adresa.3.3 Poskytovatel vynaloží přiměřené úsilí, aby byl Kurz dostupný. Kupující však bere na vědomí, že může dojít k dočasným omezením dostupnosti z důvodu údržby, aktualizací, zásahu vyšší moci nebo okolností na straně třetích osob (např. poskytovatel Platformy/hostingu)."]},{"heading":"4. Objednávka a uzavření smlouvy","paragraphs":["4.1 Kupující provádí objednávku Kurzu prostřednictvím webového rozhraní Poskytovatele.4.2 Před odesláním objednávky má Kupující možnost zkontrolovat a případně opravit zadané údaje.4.3 Odesláním objednávky Kupující potvrzuje, že se seznámil s těmito Podmínkami a souhlasí s nimi.4.4 Smlouva je uzavřena okamžikem, kdy Poskytovatel (i) potvrdí přijetí objednávky Kupujícímu e-mailem, nebo (ii) zpřístupní Kupujícímu Kurz (např. zasláním přístupových údajů či aktivací Uživatelského účtu), podle toho, co nastane dříve.4.5 Poskytovatel není povinen uzavřít Smlouvu zejména v případě zjevné chyby v ceně, zneužití systému, podezření na podvodné jednání nebo pokud Kupující dříve podstatně porušil tyto Podmínky."]},{"heading":"5. Cena, platební podmínky a měna","paragraphs":["5.1 Cena Kurzu je uvedena v Popisu Kurzu.5.2 Poskytovatel je ke dni účinnosti těchto Podmínek neplátcem DPH. V případě, že se Poskytovatel v budoucnu stane plátcem DPH, budou ceny u Kurzů uváděny a účtovány v souladu s právními předpisy, tj. buď (i) jako ceny včetně DPH, nebo (ii) jako ceny bez DPH s uvedením výše a sazby DPH; vždy podle toho, jak bude cena konkrétního Kurzu v Popisu Kurzu prezentována.5.3 Platba probíhá bezhotovostně prostřednictvím platební brány (např. Stripe) nebo jiným způsobem uvedeným v objednávkovém procesu.5.4 Platba se považuje za uhrazenou okamžikem potvrzení úspěšné transakce platební bránou nebo připsáním částky na účet Poskytovatele (dle zvoleného způsobu).5.5 Pokud je cena zobrazena orientačně v jiné měně (např. UAH), Kupující bere na vědomí, že konečný přepočet a případné poplatky určuje banka vydavatele platební karty nebo poskytovatel platebních služeb. Poskytovatel neodpovídá za kurzové rozdíly a poplatky spojené s konverzí měn.5.6 Poskytovatel neuchovává platební údaje Kupujícího; tyto údaje zpracovává přímo poskytovatel platebních služeb."]},{"heading":"6. Zpřístupnění kurzu, uživatelský účet a součinnost","paragraphs":["6.1 Po zaplacení ceny Poskytovatel zpřístupní Kupujícímu Kurz neprodleně po přijetí platby, nejpozději však do 24 hodin, není-li v Popisu Kurzu uvedeno jinak.6.2 Kupující je povinen uvést pravdivé a úplné údaje potřebné pro vytvoření Uživatelského účtu a doručování informací (zejména e-mail).6.3 Kupující je povinen chránit Přístupové údaje a zabránit jejich zpřístupnění třetím osobám. Kupující odpovídá za veškeré užití Kurzu prostřednictvím svého účtu.6.4 Poskytovatel nenese odpovědnost za nedoručení přístupových údajů v důsledku chybně zadaného e-mailu, nastavení schránky Kupujícího, filtrování spamu nebo okolností na straně Kupujícího."]},{"heading":"7. Doba přístupu ke Kurzu a změny Kurzu/Platformy","paragraphs":["7.1 Doba přístupu ke Kurzu je uvedena v Popisu Kurzu. Není-li uvedeno jinak, přístup je poskytován po dobu 12 měsíců od zpřístupnění Kurzu.7.2 Poskytovatel je oprávněn provádět přiměřené změny Kurzu a Platformy (např. aktualizace, změna pořadí modulů, změna technického řešení), pokud tím nedojde k podstatnému zhoršení dostupnosti či funkčnosti Kurzu pro Kupujícího.7.3 Pokud by změna podstatně zhoršila možnost Kupujícího Kurz užívat, má Kupující práva z vadného plnění dle čl. 10 těchto Podmínek."]},{"heading":"8. Licence a podmínky užití obsahu (duševní vlastnictví)","paragraphs":["8.1 Obsah Kurzu (zejména videa, texty, prezentace, metodiky, testy, grafika, databáze otázek a další materiály) je chráněn právními předpisy o duševním vlastnictví a náleží Poskytovateli obsahu a/nebo Poskytovateli, není-li uvedeno jinak.8.2 Poskytovatel uděluje Kupujícímu nevýhradní, nepřevoditelnou, územně neomezenou a časově omezenou licenci k užití obsahu Kurzu výhradně pro osobní vzdělávací účely Kupujícího, a to po dobu trvání přístupu ke Kurzu.8.3 Kupující nesmí zejména:a) pořizovat kopie, nahrávky obrazovky, rozmnoženiny, ani jinak reprodukovat obsah Kurzu nad rámec běžného užití pro osobní potřebu,b) sdílet Přístupové údaje, umožnit užívání Kurzu třetím osobám nebo „sdílet účet“,c) zveřejňovat, šířit, prodávat, pronajímat, sublicencovat či jinak komerčně využívat obsah Kurzu,d) obcházet technická ochranná opatření, zasahovat do Platformy nebo narušovat její bezpečnost,e) vytěžovat databázi testových otázek či obsah Kurzu automatizovanými prostředky.8.4 Porušení tohoto článku je podstatným porušením Smlouvy. Poskytovatel je v takovém případě oprávněn omezit nebo zablokovat přístup Kupujícího ke Kurzu, a to i bez předchozího upozornění, vyžaduje-li to povaha porušení. Tím nejsou dotčeny nároky Poskytovatele na náhradu škody."]},{"heading":"9. Certifikát (pokud je součástí Kurzu)","paragraphs":["9.1 Je-li v Popisu Kurzu uvedeno, že součástí Kurzu je vydání certifikátu, bude certifikát vydán za podmínek uvedených v Popisu Kurzu.9.2 Kupující bere na vědomí, že certifikát je potvrzením o absolvování Kurzu v rámci systému Poskytovatele/Poskytovatele obsahu a nemusí představovat veřejnoprávní kvalifikaci či uznání dle právních předpisů, pokud to není výslovně uvedeno.9.3 Poskytovatel je oprávněn certifikát nevydat nebo jej zneplatnit, pokud zjistí podvodné jednání (např. zneužití účtu, manipulaci s testy)."]},{"heading":"10. Odpovědnost za vady digitálního plnění a reklamace","paragraphs":["10.1 Kurz je poskytován jako digitální plnění. Poskytovatel odpovídá zejména Spotřebiteli za to, že Kurz při zpřístupnění a po dobu trvání přístupu odpovídá sjednaným vlastnostem a je bez vad.10.2 Za vadu se považuje zejména stav, kdy Kurz není dostupný, nefunguje obvyklým způsobem, neodpovídá Popisu Kurzu nebo jej nelze užívat na běžných zařízeních při splnění technických požadavků.10.3 Kupující uplatní reklamaci bez zbytečného odkladu na e-mailu info@nobel-itbs.eu a uvede popis vady, identifikaci objednávky a případně podklady umožňující vadu reprodukovat.10.4 Poskytovatel vyřídí reklamaci v přiměřené době; u Spotřebitele nejpozději ve lhůtách stanovených právními předpisy. Poskytovatel může vadu odstranit, poskytnout náhradní přístup, přiměřenou slevu z ceny nebo umožnit odstoupení od Smlouvy, vyžaduje-li to povaha vady a právní předpisy.10.5 Kupující je povinen poskytnout Poskytovateli přiměřenou součinnost nezbytnou k prověření a odstranění vady."]},{"heading":"11. Odstoupení od smlouvy, storno a refundace","paragraphs":["11.1 Je-li Kupující Spotřebitelem, má obecně právo odstoupit od Smlouvy uzavřené na dálku do 14 dnů ode dne uzavření Smlouvy, pokud nebylo zahájeno poskytování Kurzu.11.2 Kupující – Spotřebitel bere na vědomí a je tímto výslovně poučen, že Kurz je digitálním plněním, které je zpravidla zpřístupňováno bezprostředně po úhradě ceny. Odesláním objednávky a úhradou ceny Spotřebitel výslovně žádá, aby Poskytovatel zahájil poskytování Kurzu před uplynutím lhůty pro odstoupení od Smlouvy, a bere na vědomí, že okamžikem zahájení poskytování Kurzu (tj. zpřístupněním Kurzu, zejména aktivací Uživatelského účtu, zasláním přístupových údajů nebo zpřístupněním digitálních materiálů) ztrácí právo na odstoupení od Smlouvy.11.3 Pokud Spotřebitel odstoupí od Smlouvy v době, kdy ještě nedošlo k zahájení poskytování Kurzu ve smyslu čl. 11.2, Poskytovatel vrátí přijaté peněžní prostředky bez zbytečného odkladu, nejpozději ve lhůtě stanovené právními předpisy, stejným způsobem, jakým byla platba přijata, pokud se strany nedohodnou jinak.11.4 Podrobnosti k refundacím a praktickému postupu jsou uvedeny v dokumentu „Podmínky vrácení peněz / Refund Policy“ dostupném na webu Poskytovatele. V případě rozporu mezi Podmínkami vrácení peněz a těmito Podmínkami mají přednost tyto Podmínky.11.5 U Podnikatelů se právo odstoupit řídí zákonem a těmito Podmínkami; ustanovení o spotřebitelském odstoupení se nepoužijí."]},{"heading":"12. Ochrana osobních údajů","paragraphs":["12.1 Poskytovatel zpracovává osobní údaje Kupujících v souladu s platnými právními předpisy, zejména GDPR. Informace o zpracování osobních údajů jsou uvedeny v dokumentu „Zásady ochrany osobních údajů / Privacy Policy“ dostupném na webu Poskytovatele.12.2 Kupující bere na vědomí, že pro účely zpřístupnění Kurzu na Platformě a případně pro vydání certifikátu může být nezbytné předání určitých údajů Poskytovateli obsahu nebo provozovateli Platformy, a to v rozsahu nezbytném pro splnění Smlouvy."]},{"heading":"13. Jazykové verze","paragraphs":["13.1 Podmínky mohou být zpřístupněny v českém a cizojazyčném znění. V případě rozporu mezi jazykovými verzemi má přednost české znění."]},{"heading":"14. Závěrečná ustanovení, rozhodné právo a řešení sporů","paragraphs":["14.1 Smlouva a Podmínky se řídí právním řádem České republiky.14.2 Vzájemné spory se Poskytovatel a Kupující zavazují řešit přednostně smírně.14.3 Je-li Kupující Spotřebitelem, má právo na mimosoudní řešení spotřebitelského sporu. Subjektem mimosoudního řešení je Česká obchodní inspekce (ČOI). Podrobnosti jsou dostupné na webu ČOI.14.4 Pokud některé ustanovení Podmínek je nebo se stane neplatným či neúčinným, nemá to vliv na platnost ostatních ustanovení.14.5 Poskytovatel je oprávněn Podmínky v přiměřeném rozsahu měnit; změnu oznámí vhodným způsobem. Pro Kupujícího je závazné znění účinné v době uzavření Smlouvy, pokud právní předpisy nevyžadují jinak.14.6 Tyto Podmínky nabývají účinnosti dne 1. 3. 2026."]}]}'::jsonb),
((select id from public.content_pages where page_key='refund_policy'),'en','published','Refund Policy | Nobel ITBS','Full Nobel ITBS legal document: Refund Policy.','Refund Policy','{"slug":"refund-policy","blocks":[{"heading":"","paragraphs":["This document sets out the rules for withdrawal from the contract and refunds in connection with the purchase of online courses and digital content provided by NOBEL ITBS s.r.o., Company ID No.: 23465492, with its registered office at Vrážská 143, Radotín, 153 00 Prague 5, Czech Republic, registered in the Commercial Register maintained by the Municipal Court in Prague, File No. C 427524 (the “Provider”). This document is supplementary to the Terms of Use; in the event of any conflict, the Terms of Use shall prevail."]},{"heading":"1. When a refund may be requested","paragraphs":["1.1 If the customer is a consumer, they generally have the right to withdraw from a distance contract within 14 days from the date of conclusion of the contract, provided that the provision of the course/digital content has not yet begun.","1.2 A refund may be requested in the following situations:","a) the customer has paid the price, but the course has not been made available to them (for example, access credentials have not been provided, the account has not been activated, or the materials have not been made available), and at the same time the customer requests cancellation of the order within the period specified in Article 1.1;","b) a duplicate payment has been made or there has been an obvious error in the amount charged;","c) the Provider is unable to provide the performance (for example due to long-term unavailability or cancellation of the course); in such a case, the matter shall be handled according to the specific circumstances and the customer’s rights arising from defective performance."]},{"heading":"2. When a refund is not available (commencement of course provision)","paragraphs":["2.1 The customer acknowledges that the course constitutes digital content / digital performance, which is generally made available immediately after payment of the price.","2.2 Once the provision of the course has begun, the consumer loses the right to withdraw from the contract and request a refund based on withdrawal. The commencement of course provision means in particular:","a) activation of the user account for the course; or","b) sending access credentials to the platform (LMS); or","c) making digital materials available for download; or","d) any other way of making the course content available to the customer.","2.3 This does not affect the customer’s right to make a complaint or exercise rights arising from defective performance if the course does not function properly, is not available, or does not correspond to the agreed characteristics (see Article 4)."]},{"heading":"3. How to request a refund","paragraphs":["3.1 Refund requests should be sent by e-mail to: info@nobel-itbs.eu.","3.2 The request should include at least:","the customer’s name and the contact e-mail address used for the order,","identification of the payment (date, amount, currency, and, if applicable, transaction number),","the name of the course,","the reason for the request (for example withdrawal before access was granted / duplicate payment / failure to provide access).","3.3 The Provider may request additional information necessary to verify the payment and the order."]},{"heading":"4. Technical issues, complaints and defective performance","paragraphs":["4.1 If the customer is unable to use the course due to technical problems, or if the course does not correspond to the Course Description, the customer is advised to first contact support at info@nobel-itbs.eu and describe the issue (device, browser, screenshot of the error, time of occurrence).","4.2 The Provider will attempt to remedy the defect, provide substitute access, or propose another solution. If the defect cannot be remedied within a reasonable period of time, the customer may be entitled to an appropriate discount or to withdraw from the contract in accordance with applicable law and the Terms of Use.","4.3 The provisions of this Article shall also apply after the provision of the course has begun; this is a different regime from a “refund due to withdrawal”."]},{"heading":"5. Deadline and method of refund","paragraphs":["5.1 If the refund request is justified, the Provider shall refund the money without undue delay, no later than within the period required by applicable law.","5.2 The refund will be made using the same payment method that was used to make the original payment, unless agreed otherwise.","5.3 The Provider shall not be responsible for the time required to process the refund on the part of the bank or payment service provider."]},{"heading":"6. Business customers","paragraphs":["6.1 In the case of customers who are not consumers (business customers), withdrawal and refunds shall be governed by the contract, these documents, and the applicable legal regulations; consumer protection rules (including the 14-day withdrawal period) shall not apply."]},{"heading":"7. Final provisions","paragraphs":["7.1 This document is effective as of 1 March 2026.","7.2 This document is available on the Provider’s website.","7.3 In the event of any conflict between this document and the Terms of Use, the Terms of Use shall prevail."]}]}'::jsonb),
((select id from public.content_pages where page_key='refund_policy'),'ua','published','Політика повернення | Nobel ITBS','Повний юридичний документ Nobel ITBS: Політика повернення.','Політика повернення','{"slug":"refund-policy","blocks":[{"heading":"","paragraphs":["щодо надання онлайн-освітніх курсів компанією NOBEL ITBS s.r.o.","Цей документ установлює правила відмови від договору та повернення коштів у зв''язку з придбанням онлайн-курсів і цифрового контенту, що надаються NOBEL ITBS s.r.o., ідентифікаційний номер 23465492, зареєстрований офіс: Vrážská 143, Radotín, 153 00 Praha 5, Czech Republic, зареєстрована в Торговому реєстрі, який веде Міський суд у Празі, справа № C 427524 («Постачальник»). Документ доповнює Умови використання; у разі суперечності перевагу мають Умови."]},{"heading":"1. Коли можна вимагати повернення коштів","paragraphs":["1.1. Якщо замовник є Споживачем, він загалом має право відмовитися від дистанційного договору протягом 14 днів від його укладення за умови, що надання Курсу або цифрового контенту ще не почалося.","1.2. Повернення можна вимагати, якщо:","a) ціну сплачено, але Курс не надано — дані доступу не надіслані, обліковий запис не активований або матеріали не відкриті — і замовник просить скасувати замовлення в строк, установлений пунктом 1.1;","b) здійснено подвійний платіж або сталася очевидна помилка в сумі списання;","c) Постачальник не може надати послугу, наприклад через тривалу недоступність або скасування Курсу. У такому разі питання вирішується з урахуванням конкретних обставин і прав замовника у зв''язку з неналежним виконанням."]},{"heading":"2. Коли повернення через відмову недоступне","paragraphs":["2.1. Курс є цифровим контентом або цифровим виконанням, яке зазвичай надається одразу після оплати.","2.2. Після початку надання Курсу Споживач втрачає право відмовитися від договору та вимагати повернення на підставі відмови. Початком надання, зокрема, є:","a) активація облікового запису;","b) надсилання даних доступу до Платформи/LMS;","c) відкриття цифрових матеріалів для завантаження;","d) будь-який інший спосіб надання замовникові доступу до контенту Курсу.","2.3. Це не обмежує право подати скаргу або скористатися правами у зв''язку з неналежним виконанням, якщо Курс не працює, недоступний або не відповідає погодженим характеристикам."]},{"heading":"3. Як подати запит на повернення","paragraphs":["3.1. Запит надсилається на info@nobel-itbs.eu.","3.2. У запиті потрібно зазначити щонайменше:","- ім''я замовника та контактний email, використаний у замовленні; - дату, суму, валюту й, за наявності, номер транзакції; - назву Курсу; - причину запиту, наприклад відмову до відкриття доступу, подвійний платіж або ненадання доступу.","3.3. Постачальник може запросити додаткові дані для перевірки платежу й замовлення."]},{"heading":"4. Технічні проблеми, скарги та неналежне виконання","paragraphs":["4.1. Якщо Курс неможливо використовувати через технічні проблеми або він не відповідає Опису, замовникові рекомендовано звернутися на info@nobel-itbs.eu та описати проблему, пристрій, браузер, час виникнення й, за можливості, додати знімок екрана.","4.2. Постачальник спробує усунути недолік, надати альтернативний доступ або інше рішення. Якщо недолік не усунуто в розумний строк, замовник може мати право на відповідну знижку або відмову згідно із законом та Умовами використання.","4.3. Ця стаття застосовується і після початку надання Курсу та є окремою від режиму повернення через відмову."]},{"heading":"5. Строк і спосіб повернення","paragraphs":["5.1. Якщо запит обґрунтований, кошти повертаються без невиправданої затримки, не пізніше строку, установленого законодавством.","5.2. Повернення здійснюється тим самим способом, яким було виконано первинний платіж, якщо не погоджено інше.","5.3. Постачальник не відповідає за строк оброблення повернення банком або платіжним провайдером."]},{"heading":"6. Бізнес-клієнти","paragraphs":["6.1. Для замовників, які не є Споживачами, відмова й повернення регулюються договором, цими документами та застосовним правом. Споживчі правила, включно з 14-денним строком, не застосовуються."]},{"heading":"7. Прикінцеві положення","paragraphs":["7.1. Документ набирає чинності 1 березня 2026 року.","7.2. Документ доступний на вебсайті Постачальника.","7.3. У разі суперечності з Умовами використання перевагу мають Умови."]}]}'::jsonb),
((select id from public.content_pages where page_key='refund_policy'),'cz','published','Podmínky vrácení peněz | Nobel ITBS','Úplný právní dokument Nobel ITBS: Podmínky vrácení peněz.','Podmínky vrácení peněz','{"slug":"refund-policy","blocks":[{"heading":"","paragraphs":["Tento dokument stanoví pravidla pro odstoupení od smlouvy a vrácení peněz v souvislosti s nákupem online kurzů a digitálního obsahu poskytovaného společností NOBEL ITBS s.r.o., IČO: 23465492, se sídlem Vrážská 143, Radotín, 153 00 Praha 5, zapsanou v obchodním rejstříku vedeném Městským soudem v Praze, sp. zn. C 427524 („Poskytovatel“). Tento dokument je doplňkový k Podmínkám používání; v případě rozporu mají přednost Podmínky používání."]},{"heading":"1. Kdy lze žádat o vrácení peněz","paragraphs":["1.1 Pokud je zákazník spotřebitelem, má obecně právo odstoupit od smlouvy uzavřené na dálku do 14 dnů od uzavření smlouvy, pokud ještě nebylo zahájeno poskytování kurzu/digitálního plnění.1.2 Vrácení peněz je možné zejména v těchto situacích:a) zákazník uhradil cenu, ale kurz mu nebyl zpřístupněn (např. nebyly poskytnuty přístupové údaje, nebyl aktivován účet, nebyly zpřístupněny materiály), a zároveň požádá o zrušení objednávky ve lhůtě dle čl. 1.1;b) došlo k duplicitní platbě nebo zjevné chybě při stržení částky;c) Poskytovatel nemůže plnění poskytnout (např. dlouhodobá nedostupnost, zrušení kurzu) – v takovém případě se postupuje podle konkrétních okolností a práva zákazníka z vadného plnění."]},{"heading":"2. Kdy vrácení peněz možné není (zahájení poskytování kurzu)","paragraphs":["2.1 Zákazník bere na vědomí, že kurz je digitálním plněním, které je zpravidla zpřístupňováno bezprostředně po úhradě ceny.2.2 Okamžikem zahájení poskytování kurzu zaniká spotřebiteli právo odstoupit od smlouvy a žádat vrácení peněz z důvodu odstoupení. Zahájením poskytování kurzu se rozumí zejména:a) aktivace uživatelského účtu pro kurz, nebob) zaslání přístupových údajů k platformě (LMS), neboc) zpřístupnění digitálních materiálů ke stažení, nebod) jiné zpřístupnění obsahu kurzu zákazníkovi.2.3 Tím není dotčeno právo zákazníka uplatnit reklamaci nebo práva z vadného plnění, pokud kurz nefunguje, není dostupný nebo neodpovídá sjednaným vlastnostem (viz čl. 4)."]},{"heading":"3. Jak požádat o vrácení peněz","paragraphs":["3.1 Žádost o vrácení peněz zašlete na e-mail info@nobel-itbs.eu.3.2 V žádosti uveďte alespoň:","jméno a kontaktní e-mail použitý při objednávce,","identifikaci platby (datum, částka, měna, případně číslo transakce),","název kurzu,","důvod žádosti (např. odstoupení před zpřístupněním / duplicitní platba / nedodání přístupu).3.3 Poskytovatel může požádat o doplnění údajů nezbytných k ověření platby a objednávky."]},{"heading":"4. Technické problémy, reklamace a vadné plnění","paragraphs":["4.1 Pokud zákazník kurz nemůže užívat z důvodu technických problémů nebo kurz neodpovídá Popisu kurzu, doporučuje se nejprve kontaktovat podporu na info@nobel-itbs.eu a popsat problém (zařízení, prohlížeč, screenshot chyby, čas výskytu).4.2 Poskytovatel se pokusí vadu odstranit, poskytnout náhradní přístup nebo navrhnout jiné řešení. Pokud vadu nelze odstranit v přiměřené době, může mít zákazník nárok na přiměřenou slevu nebo odstoupení od smlouvy podle právních předpisů a Podmínek používání.4.3 Ustanovení tohoto článku platí i po zahájení poskytování kurzu; jde o jiný režim než „vrácení z důvodu odstoupení“."]},{"heading":"5. Lhůta a způsob vrácení peněz","paragraphs":["5.1 Pokud je žádost o vrácení peněz oprávněná, Poskytovatel vrátí peníze bez zbytečného odkladu, nejpozději ve lhůtě stanovené právními předpisy.5.2 Peníze budou vráceny stejným způsobem, jakým byla platba přijata, není-li dohodnuto jinak.5.3 Poskytovatel nenese odpovědnost za dobu zpracování vrácení platby na straně banky nebo poskytovatele platebních služeb."]},{"heading":"6. Podnikatelé","paragraphs":["6.1 U zákazníků, kteří nejsou spotřebiteli (podnikatelé), se odstoupení a vrácení peněz řídí smlouvou, těmito dokumenty a příslušnými právními předpisy; spotřebitelská pravidla (včetně 14denní lhůty) se neuplatní."]},{"heading":"7. Závěrečná ustanovení","paragraphs":["7.1 Tento dokument je účinný od 1. 3. 2026.7.2 Tento dokument je dostupný na webových stránkách Poskytovatele.7.3 V případě rozporu mezi tímto dokumentem a Podmínkami používání mají přednost Podmínky používání."]}]}'::jsonb)
